// calculations.js
export class OperationProcessor {
    constructor(operations) {
      this.operations = operations;
    }

    conteo() {
      return this.operations.length;
    }

    promedio(operationType) {
      const flattenValue = (value) => {
        if (Array.isArray(value)) {
          return value.reduce((acc, el) => acc + flattenValue(el.valor1 || 0), 0);
        }
        return typeof value === 'number' ? value : 0;
      };

      let sum = 0, count = 0;
      for (let op of this.operations) {
        if (op.operacion === operationType) {
          const v1 = op.valor1 || 0;
          const v2 = flattenValue(op.valor2);
          sum += (v1 + v2) / 2;
          count++;
        }
      }
      return count ? sum / count : 0;
    }

    max(operationType) {
      const flattenMax = (value) => {
        if (Array.isArray(value)) {
          return value.reduce((max, el) => Math.max(max, flattenMax(el.valor1 || 0)), -Infinity);
        }
        return typeof value === 'number' ? value : -Infinity;
      };

      let maxValue = -Infinity;
      for (let op of this.operations) {
        if (op.operacion === operationType) {
          const v1 = op.valor1 || -Infinity;
          const v2 = flattenMax(op.valor2);
          maxValue = Math.max(maxValue, v1, v2);
        }
      }
      return maxValue;
    }

    min(operationType) {
      let minValue = Infinity;
      for (let op of this.operations) {
        if (op.operacion === operationType && op.valor1 !== undefined && op.valor2 !== undefined) {
          minValue = Math.min(minValue, op.valor1, op.valor2);
        }
      }
      return minValue;
    }
  }
